contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 firstAmount, uint256 secondAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (firstAmount) + (secondAmount)); require(firstAmount <= 1000000000000000000000000000000); require(secondAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= firstAmount + secondAmount, "insufficient balance");

        uint256 beforeFirst = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: firstAmount}(); if (__ESBMC_reverted()) return;
        uint256 midBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: secondAmount}(); if (__ESBMC_reverted()) return;
        uint256 finalBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(finalBalance == beforeFirst + firstAmount + secondAmount && midBalance == beforeFirst + firstAmount);
    }

    receive() external payable {}
}

