import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 firstAmount, uint256 secondAmount) internal {
        firstAmount = bound(firstAmount, 0, 1000000000000000000000000000000);
        secondAmount = bound(secondAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= firstAmount + secondAmount);
        uint256 beforeFirst;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeFirst = __r; } catch { return; }
        try c.addToBalance{value: firstAmount}() {} catch { return; }
        uint256 midBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { midBalance = __r; } catch { return; }
        try c.addToBalance{value: secondAmount}() {} catch { return; }
        uint256 finalBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { finalBalance = __r; } catch { return; }
        assertTrue(finalBalance == beforeFirst + firstAmount + secondAmount && midBalance == beforeFirst + firstAmount);
    }

    function testFuzz_run(uint256 firstAmount, uint256 secondAmount) public {
        _run(firstAmount, secondAmount);
    }

    receive() external payable {}
}
